    def on_add_dof_keyframe(self):
        if not self.doc:
            return
        frame = getattr(self, "cur_frame", 0) or 0
        menu = QtWidgets.QMenu(self.main_window)
        menu.setStyleSheet("QMenu { background-color: #1e293b; color: #f8fafc; border: 1px solid #475569; padding: 4px; }"
                           "QMenu::item { padding: 4px 20px 4px 20px; }"
                           "QMenu::item:selected { background-color: #3b82f6; }")
        title_act = menu.addAction(f"── Add 9-DOF Keyframe (Frame {frame + 1}) ──")
        title_act.setEnabled(False)

        seg_actions = {}
        for seg_id in range(1, 10):
            name = self.doc.dof_segment_names.get(seg_id, f"Segment {seg_id}") if hasattr(self.doc, "dof_segment_names") else f"Segment {seg_id}"
            act = menu.addAction(f"Angle {seg_id}: {name}")
            seg_actions[act] = seg_id

        selected = menu.exec_(QtGui.QCursor.pos())
        if selected in seg_actions:
            chosen_seg = seg_actions[selected]
            self.doc.add_dof_keyframe(frame, segment_idx=chosen_seg)
            self.main_window.waveform_view.viewport().update()
            self.main_window.mouth_view.draw_me(force=True)
            self.main_window.statusbar.showMessage(f"Added 9-DOF Angle {chosen_seg} keyframe at Frame {frame + 1}", 4000)

    def on_apply_speed(self):
        if not self.doc:
            return
        val = self.speed_spin.value()
        if abs(val - 1.0) < 0.001:
            return
        self.doc.scale_lip_sync_speed(val)
        self.main_window.waveform_view.set_document(self.doc, True, True)
        self.main_window.mouth_view.draw_me(force=True)
        self.main_window.statusbar.showMessage(f"Scaled lip-sync timing by {val:.2f}x", 4000)
        self.speed_spin.setValue(1.00)

    def on_tts_synthesize(self):
        if not self.doc:
            return
        default_txt = ""
        if self.doc.current_voice and self.doc.current_voice.text:
            default_txt = self.doc.current_voice.text
        dlg = TTSSynthesizeDialog(self.main_window, default_txt)
        if dlg.exec_() == QtWidgets.QDialog.Accepted:
            txt = dlg.get_text()
            gen = dlg.get_gender()
            lang = self.main_window.language_choice.currentText()
            out = self.doc.generate_tts_audio(text=txt, language=lang, gender=gen)
            if out:
                if self.doc.current_voice:
                    self.main_window.text_edit.setText(self.doc.current_voice.text)
                self.main_window.waveform_view.set_document(self.doc, True, True)
                self.main_window.mouth_view.draw_me(force=True)
                self.main_window.statusbar.showMessage("TTS Audio synthesized and breakdown populated successfully!", 5000)

    def on_voice_effector(self):
        if not self.doc or not self.doc.soundPath:
            QtWidgets.QMessageBox.information(self.main_window, "Voice Effector", "Please open or generate an audio file first.")
            return
        dlg = VoiceEffectorDialog(self.main_window)
        if dlg.exec_() == QtWidgets.QDialog.Accepted:
            preset = dlg.get_preset()
            pitch = dlg.get_pitch()
            spd = dlg.get_speed()
            out = self.doc.apply_voice_effect(preset=preset, pitch_semitones=pitch, speed_multiplier=spd)
            if out:
                self.main_window.waveform_view.set_document(self.doc, True, True)
                self.main_window.mouth_view.draw_me(force=True)
                self.main_window.statusbar.showMessage(f"Voice effect '{preset}' applied successfully!", 5000)

    def set_preview_mode(self, mode):
        if hasattr(self.main_window, "mouth_view"):
            self.main_window.mouth_view.view_mode = mode
            self.main_window.mouth_view.draw_me(force=True)
            mode_names = {"auto": "Auto Layout", "single": "Single View", "split": "Split View", "grid_2x2": "2x2 Grid"}
            self.main_window.statusbar.showMessage(f"Preview Layout set to: {mode_names.get(mode, mode)}", 3000)

    def populate_mouth_set_menu(self):
        if not hasattr(self, "mouth_set_menu"):
            return
        self.mouth_set_menu.clear()
        mouth_view = getattr(self.main_window, "mouth_view", None)
        if not mouth_view or not hasattr(mouth_view, "mouths"):
            return
        for m_name in sorted(mouth_view.mouths.keys()):
            act = self.mouth_set_menu.addAction(m_name)
            act.setCheckable(True)
            act.setChecked(m_name == mouth_view.current_mouth)
            act.triggered.connect(partial(self.on_switch_mouth_from_menu, m_name))

    def on_switch_mouth_from_menu(self, mouth_name):
        idx = self.main_window.mouth_choice.findText(mouth_name)
        if idx >= 0:
            self.main_window.mouth_choice.setCurrentIndex(idx)
        elif hasattr(self.main_window, "mouth_view"):
            self.main_window.mouth_view.set_mouth(mouth_name)
        self.populate_mouth_set_menu()
        self.main_window.statusbar.showMessage(f"Viseme Mouth Set switched to: {mouth_name}", 3000)

